package arvind.neetcode;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class FindAllAnagramsInString {

    public List<Integer> findAnagrams(String s, String p) {
        HashMap<Character, Integer> pmap = new HashMap<>();
        HashMap<Character, Integer> smap = new HashMap<>();
        List<Integer> result = new ArrayList<>();

        if (p.length() > s.length()) {
            return new ArrayList();
        }

        for (char c : p.toCharArray()) {
            pmap.put(c, pmap.getOrDefault(c, 0)+ 1);
        }
        int l =0;
        int h = p.length() - 1;

        for (int i=0; i<p.length(); i++) {
            smap.put(s.charAt(i), smap.getOrDefault(s.charAt(i), 0)+1);
        }

        while (h < s.length()) {
            if (contains(smap, pmap)) {
                result.add(l);
            }
            // remove l index char from smap
            smap.put(s.charAt(l), smap.get(s.charAt(l))-1);

            h += 1;
            // add next h index char to smap
            if (h < s.length())
                smap.put(s.charAt(h), smap.getOrDefault(s.charAt(h), 0) + 1);
            l += 1;
        }

        return result;
    }

    private boolean contains(HashMap<Character, Integer> smap, HashMap<Character, Integer> pmap) {
        for (Map.Entry<Character, Integer> entry : pmap.entrySet()) {
            if (!smap.containsKey(entry.getKey())) {
                return false;
            }
            if (smap.get(entry.getKey()).compareTo(entry.getValue()) != 0) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        FindAllAnagramsInString solution = new FindAllAnagramsInString();
        String s = "";
        String p = "";
        List<Integer> result = solution.findAnagrams(s, p);
        System.out.println(result);
    }
}
